    function normalizeMaterialName(name) {
        const s = String(name || '').trim()
        if (!s) return s
    
        // уже материал: "(м)" или "(m)" в конце
        if (/\((?:м|m)\)\s*$/i.test(s)) return s.replace(/\((?:м|m)\)\s*$/i, '(м)')
    
        return s + ' (м)'
    }
    
    function isMaterialItem(name) {
        return /\((?:м|m)\)\s*$/i.test(String(name || '').trim())
    }
        
    function stripMaterialSuffix(name) {
        return String(name || '').trim().replace(/\((?:м|m)\)\s*$/i, '').trim()
    }

    function findMaterialKeyByName(name) {
        // ищем в MATERIAL_INFO_MAP нечувствительно к регистру
        const base = stripMaterialSuffix(name)
        return findKeyInsensitiveIn(MATERIAL_INFO_MAP || {}, base) // вернёт реальный ключ или null
    }
    
    function canonicalInventoryName(rawName) {
        const s = String(rawName || '').trim()
        if (!s) return s
    
        const matKey = findMaterialKeyByName(s)
        if (matKey) return normalizeMaterialName(matKey) // гарантированно "... (м)"
    
        // если это уже "(м)" но в словаре почему-то нет — оставим как есть, только нормализуем суффикс
        if (isMaterialItem(s)) return normalizeMaterialName(stripMaterialSuffix(s))
    
        return s
    }

