    function toNumber(x, fallback) {
        const n = parseFloat(String(x).replace(',', '.'))
        return isNaN(n) ? (fallback === undefined ? 0 : fallback) : n
    }

    function clamp0(n) {
        n = toNumber(n, 0)
        return n < 0 ? 0 : n
    }

    function nice2(n) {
        n = toNumber(n, 0)
        return Math.round(n * 100) / 100
    }
    
    function nice0(n) {
        n = toNumber(n, 0)
        return Math.round(n)
    }

    function formatCompactInt(n) {
        n = Math.floor(toNumber(n, 0))
        if (n < 1000) return String(n)
        if (n < 10000) {
            const x = Math.round(n / 100) / 10
            return String(x).replace(/\.0$/, '') + "k"
        }
        if (n < 1000000) return String(Math.round(n / 1000)) + "k"
        if (n < 10000000) {
            const x = Math.round(n / 100000) / 10
            return String(x).replace(/\.0$/, '') + "M"
        }
        return String(Math.round(n / 1000000)) + "M"
    }

    // ВАЖНО: эта функция не вызывает getStore (безопасна в миграциях)
    function findKeyInsensitiveIn(items, targetName) {
        const t = String(targetName || '').trim().toLowerCase()
        if (!t) return null
        const keys = Object.keys(items || {})
        for (let i = 0; i < keys.length; i++) {
            const k = keys[i]
            if (String(k).toLowerCase() === t) return k
        }
        return null
    }

