    function migrateCoins(store) {
        store.coins = store.coins || { mm: 0, sm: 0, zm: 0, pm: 0 }

        const map = {
            'мм': 'mm',
            'см': 'sm',
            'зм': 'zm',
            'пм': 'pm',
            'ММ': 'mm',
            'СМ': 'sm',
            'ЗМ': 'zm',
            'ПМ': 'pm'
        }

        Object.keys(store.coins).forEach(k => {
            const nk = map[k]
            if (!nk) return
            if (store.coins[nk] === undefined) store.coins[nk] = 0
            store.coins[nk] = toNumber(store.coins[nk], 0) + toNumber(store.coins[k], 0)
            delete store.coins[k]
        })

        const coinKeys = ['mm', 'sm', 'zm', 'pm']
        coinKeys.forEach(k => {
            store.coins[k] = Math.floor(clamp0(store.coins[k]))
        })
    }

    function migrateItems(store) {
        store.items = store.items || {}

        // cleanup broken keys like "undefined" / "null" / empty
        Object.keys(store.items).forEach(k => {
            const lowk = String(k || '').trim().toLowerCase()
            if (!lowk || lowk === 'undefined' || lowk === 'null') {
                delete store.items[k]
                return
            }

            const it = store.items[k]
            if (!it) {
                delete store.items[k]
                return
            }

            const nm = String(it.name || k).trim()
            const lown = nm.toLowerCase()
            if (!nm || lown === 'undefined' || lown === 'null') {
                delete store.items[k]
                return
            }
        })
        
        const keys = Object.keys(store.items)

        keys.forEach(k => {
            const it = store.items[k]
            if (!it) return

            const keyTrim = String(k || '').trim()
            const keyLow = keyTrim.toLowerCase()

            // убираем битые записи (undefined/null/пустые ключи)
            if (!keyTrim || keyLow === 'undefined' || keyLow === 'null') {
                delete store.items[k]
                return
            }

            // инструменты больше не хранятся как предметы инвентаря скрипта
            // удаляем только "технические" маркеры (вес = 0)
            if (keyLow.indexOf('инструменты') === 0) {
                const uw = toNumber((it.unitWeight !== undefined ? it.unitWeight : it.weight), 0)
                if (uw === 0) {
                    delete store.items[k]
                    return
                }
            }

            // гарантируем, что name есть всегда
            if (it.name === undefined || it.name === null || String(it.name).trim() === '') it.name = keyTrim
            if (it.qty !== undefined && it.unitWeight !== undefined) {
                it.qty = nice2(it.qty)
                it.unitWeight = nice2(it.unitWeight)
                return
            }

            const w = toNumber(it.weight, 0)
            store.items[k] = {
                name: it.name || k,
                qty: 1,
                unitWeight: nice2(w)
            }
        })

        // Еда/вода: если было "qty=1 unitWeight=TOTAL", превращаем в "qty=TOTAL unitWeight=1"
        const supplyNames = [FOOD_ITEM_NAME, WATER_ITEM_NAME]
        supplyNames.forEach(nm => {
            const key = findKeyInsensitiveIn(store.items, nm)
            if (!key) return
            const it = store.items[key]
            if (!it) return

            if (toNumber(it.qty, 0) === 1 && toNumber(it.unitWeight, 0) > 0) {
                store.items[key] = {
                    name: nm,
                    qty: nice2(it.unitWeight),
                    unitWeight: 1
                }
            }
        })
    }

    function migrateParty(store) {
        store.party = store.party || {}
        store.party.members = store.party.members || {}

        const legacy = store.party.capacityMod
        if (store.party.defaultCapMod === undefined || store.party.defaultCapMod === null || store.party.defaultCapMod === '') {
            store.party.defaultCapMod = toNumber(legacy, 15) || 15
        }
        store.party.defaultCapMod = toNumber(store.party.defaultCapMod, 15) || 15

        Object.keys(store.party.members).forEach(id => {
            const m = store.party.members[id]
            if (!m) return
            if (!m.role) m.role = 'member'
            if (m.capBonusLb === undefined || m.capBonusLb === null || isNaN(toNumber(m.capBonusLb, NaN))) m.capBonusLb = 0
            if (m.energyCur === undefined) m.energyCur = null
            if (m.energyMaxOverride === undefined) m.energyMaxOverride = null
            if (m.conModOverride === undefined) m.conModOverride = null
            m.heroDoll = m.heroDoll || {}
            m.heroDoll.slots = m.heroDoll.slots || {}
        })
    }


