    function findItemKeyInsensitive(targetName) {
        const store = getStore()
        return findKeyInsensitiveIn(store.items, targetName)
    }

    function getItemByName(name) {
        const store = getStore()
        const key = findKeyInsensitiveIn(store.items, name)
        if (!key) return null
        return store.items[key] || null
    }

    function getItemTotalWeightByName(name) {
        const it = getItemByName(name)
        if (!it) return 0
        return nice2(toNumber(it.qty, 0) * toNumber(it.unitWeight, 0))
    }

    function getItemWeightByName(name) {
        return getItemTotalWeightByName(name)
    }

    function setItemWeightByName(name, newTotalWeight) {
        const store = getStore()
        const key = findKeyInsensitiveIn(store.items, name) || name
        newTotalWeight = nice2(newTotalWeight)

        if (newTotalWeight <= 0) {
            delete store.items[key]
            return
        }

        store.items[key] = store.items[key] || { name: key, qty: 0, unitWeight: 1 }
        store.items[key].name = key
        store.items[key].qty = nice2(newTotalWeight)
        store.items[key].unitWeight = 1
    }

    function addItemWeightByName(name, deltaTotalWeight) {
        const w = getItemTotalWeightByName(name)
        setItemWeightByName(name, w + toNumber(deltaTotalWeight, 0))
    }

    function getTotalLootWeight() {
        const store = getStore()
        const items = store.items || {}
        return Object.keys(items).reduce((sum, k) => {
            const it = items[k]
            return sum + (toNumber(it && it.qty, 0) * toNumber(it && it.unitWeight, 0))
        }, 0)
    }

    function getTotalLootQty() {
        const store = getStore()
        const items = store.items || {}
        return Object.keys(items).reduce((sum, k) => sum + toNumber(items[k] && items[k].qty, 0), 0)
    }

    function parseWeightFromInfo(name) {
        const rec = getLootInfoByName(name)
        const info = rec.info
        if (!info) return 0

        if (rec.source === 'magic') return 2
        if (!info.weight && isMagicItemName(name)) return 2
        if (!info.weight) return 0
        const m = String(info.weight).match(/-?\d+([.,]\d+)?/g)
        if (!m) return 0
        return toNumber(m[0], 0)
    }
    
    // ───────────────────────────────────────────────────────────────────────────
    // LOOTGEN (генератор лута из LOOT_INFO_MAP)
    // ───────────────────────────────────────────────────────────────────────────

    function sayPublic(html) {
        sendChat(SCRIPT_NAME, '/direct ' + html)
    }

    function getLootGenStore() {
        const store = getStore()
        store.lootgen = store.lootgen || {}
        store.lootgen.items = store.lootgen.items || {} // name -> { qty, value, unitWeight }
        store.lootgen.coins = store.lootgen.coins || { pm: 0, zm: 0, sm: 0, mm: 0 }
        return store.lootgen
    }

    function lootgenCoinModeEnabled(raw) {
        const mode = String(raw || 'нет').trim().toLowerCase()
        return (mode === 'да' || mode === 'yes' || mode === '1' || mode === 'true')
    }

    function splitMmToBalancedCoins(totalMm) {
        let mm = Math.max(0, Math.floor(toNumber(totalMm, 0)))
        const out = { pm: 0, zm: 0, sm: 0, mm: 0 }
        if (mm <= 0) return out

        const pmMax = Math.floor(mm / 1000)
        out.pm = pmMax > 0 ? randomInteger(pmMax + 1) - 1 : 0
        mm -= out.pm * 1000

        const zmMax = Math.floor(mm / 100)
        out.zm = zmMax > 0 ? randomInteger(zmMax + 1) - 1 : 0
        mm -= out.zm * 100

        const smMax = Math.floor(mm / 10)
        out.sm = smMax > 0 ? randomInteger(smMax + 1) - 1 : 0
        mm -= out.sm * 10

        out.mm = mm
        return out
    }

    function lootgenTakeCoins(playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const lg = getLootGenStore()
        const c = lg.coins || { pm: 0, zm: 0, sm: 0, mm: 0 }
        const addMm = coinsToMm(c)
        if (addMm <= 0) return renderLootGenToChat()

        const store = getStore()
        const curMm = coinsToMm(store.coins || {})
        store.coins = mmToCoins(curMm + addMm)
        lg.coins = { pm: 0, zm: 0, sm: 0, mm: 0 }

        renderLootGenToChat(["• Монеты: " + htmlEscape(coinsToText(c))])
    }

    function lootgenClear(playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const lg = getLootGenStore()
        lg.items = {}
        lg.coins = { pm: 0, zm: 0, sm: 0, mm: 0 }
        renderLootGenToChat()
    }

    function lootgenTakeOne(rawName, playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const name = String(rawName || '').trim()
        if (!name) return renderLootGenToChat()

        const lg = getLootGenStore()
        const rec = lg.items[name]
        if (!rec) return renderLootGenToChat()

        // перенести 1 шт в инвентарь
        addOrUpdateLoot(name + "||+1", playerid)

        // уменьшить в пуле
        rec.qty = toNumber(rec.qty, 0) - 1
        if (rec.qty <= 0) delete lg.items[name]

        renderLootGenToChat()
    }
    
    function lootgenTakeType(rawName, playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const name = String(rawName || '').trim()
        if (!name) return renderLootGenToChat()

        const lg = getLootGenStore()
        const key = findKeyInsensitiveIn(lg.items, name)
        if (!key) return renderLootGenToChat()

        const rec = lg.items[key]
        if (!rec) return renderLootGenToChat()

        const q = Math.floor(toNumber(rec.qty, 0))
        if (q <= 0) {
            delete lg.items[key]
            return renderLootGenToChat()
        }

        invAddQtySilent(key, q, rec.unitWeight)
        delete lg.items[key]

        renderLootGenToChat(["• " + htmlEscape(key) + " × " + htmlEscape(q)])
    }

    function parseTypesList(raw) {
        const s = String(raw || '').trim()
        if (!s) return []
        return s
            .split(/[,;]/g)
            .map(x => String(x || '').trim())
            .filter(Boolean)
            .map(x => x.toLowerCase())
    }

    function isMagicItem(info) {
        if (!info) return false
        if (info.magic === true) return true
        const t = String(info.type || '').toLowerCase()
        return t.indexOf('маг') !== -1
    }

    function filterCandidatesByParams(typesList, magicMode) {
        const keys = Object.keys(LOOT_INFO_MAP || {})
        const wantAnyType = !typesList.length || typesList.includes('любой') || typesList.includes('any')

        const mode = String(magicMode || 'нет').trim().toLowerCase()
        // режимы:
        // нет     -> исключаем магическое
        // да      -> разрешаем и то и то
        // только  -> только магическое
        const allowMagic = (mode === 'да' || mode === 'yes' || mode === '1' || mode === 'true')
        const onlyMagic = (mode === 'только' || mode === 'only')

        const out = []

        keys.forEach(name => {
            const info = LOOT_INFO_MAP[name]
            if (!info) return

            const v = toNumber(info.value, NaN)
            if (isNaN(v) || v <= 0) return

            const w = parseWeightFromInfo(name)
            if (w <= 0) return

            const t = String(info.type || '').trim().toLowerCase()
            if (!wantAnyType) {
                if (!t) return
                if (!typesList.includes(t)) return
            }

            const magic = isMagicItem(info)
            if (onlyMagic && !magic) return
            if (!allowMagic && !onlyMagic && magic) return

            out.push({
                name,
                value: Math.floor(v),
                unitWeight: nice2(w)
            })
        })

        return out
    }

    function pickAffordable(list, remaining, excludeNames) {
        excludeNames = excludeNames || {}
        const afford = list
            .filter(x => x && x.value <= remaining && !excludeNames[x.name])

        if (!afford.length) return null

        // немного вариативности: берём случайно из топ-N по value
        afford.sort((a, b) => b.value - a.value)
        const topN = Math.min(5, afford.length)
        const idx = randomInteger(topN) - 1
        return afford[idx]
    }

    function invAddQtySilent(name, deltaQty, fallbackUnitW) {
        const nm = String(name || '').trim()
        const low = nm.toLowerCase()
        if (!nm || low === 'undefined' || low === 'null') return

        const store = getStore()
        const key = findKeyInsensitiveIn(store.items, nm) || nm
        const it = store.items[key]

        const curQty = it ? toNumber(it.qty, 0) : 0
        const nextQty = curQty + toNumber(deltaQty, 0)

        if (nextQty <= 0) {
            delete store.items[key]
            return
        }

        const unitW = (it && toNumber(it.unitWeight, 0) > 0)
            ? nice2(it.unitWeight)
            : nice2(fallbackUnitW)

        store.items[key] = {
            name: key,
            qty: nice2(nextQty),
            unitWeight: nice2(unitW)
        }
    }

    function renderLootGenToChat(receiptLines) {
        const lg = getLootGenStore()
        const items = lg.items || {}
        const names = Object.keys(items).sort((a, b) => a.localeCompare(b, 'ru'))

        // грузоподъёмность как в меню группы
        const members = getPartyMembersList({ includeMissing: false })
        let totalCapacity = 0
        members.forEach(m => {
            const eff = getMemberEffectiveStr(m.id)
            const capMod = getMemberCapMod(m.id)
            const capBonus = getMemberCapacityBonusLb(m.id)
            totalCapacity += (toNumber(eff.str, 0) * toNumber(capMod, 0)) + toNumber(capBonus, 0)
        })

        const usedWeight = nice2(getTotalLootWeight())
        const freeCapacity = nice2(totalCapacity - usedWeight)

        const capBlock =
            renderProgressBar(usedWeight, totalCapacity) +
            "<div style='margin:4px 0; color:#aaa; font-size:0.9em; text-align:left;'>" +
            "Свободно: <b style='color:#fff;'>" + htmlEscape(freeCapacity) + "</b> фнт" +
            "</div>"

        const topBtns =
            "<div style='text-align:left; margin:6px 0;'>" +
            btn('⬇ Всё в инвентарь', 'loot-tracker --lootgen-take-all', 'Перенести весь сгенерированный лут в групповой инвентарь') +
            btn('🪙 Забрать монеты', 'loot-tracker --lootgen-take-coins', 'Забрать только сгенерированные монеты') +
            btn('🧹 Очистить', 'loot-tracker --lootgen-clear', 'Очистить ТОЛЬКО список сгенерированного лута (инвентарь не трогается)') +
            "</div>"

        const coinsRec = lg.coins || { pm: 0, zm: 0, sm: 0, mm: 0 }
        const coinsMm = coinsToMm(coinsRec)
        const coinsBlock =
            "<div style='text-align:left; margin:4px 0 8px 0; color:#ccc;'>" +
            "Монеты: <b style='color:#fff;'>" + htmlEscape(coinsToText(coinsRec)) + "</b>" +
            (coinsMm > 0 ? " <span style='color:#777;'>(" + htmlEscape(mmToTradeText(coinsMm)) + ")</span>" : "") +
            "</div>"

        const receiptBlock = (receiptLines && receiptLines.length)
            ? (
                "<div style='text-align:left; margin:6px 0; color:#fff;'>" +
                "<div style='font-weight:bold; margin-bottom:4px;'>Добавлено в инвентарь:</div>" +
                "<div style='color:#ccc; font-size:0.95em;'>" + receiptLines.join("<br/>") + "</div>" +
                "</div>" +
                "<hr style='border:0;border-top:1px solid #555;margin:8px 0;'/>"
            )
            : ""

        const body = names.length
            ? names.map(nm => {
                const rec = items[nm]
                const q = Math.floor(toNumber(rec && rec.qty, 0))
                const unitW = nice2(toNumber(rec && rec.unitWeight, 0))
                const totalW = nice2(q * unitW)

                const isMat = isMaterialItem(nm)
                const infoCmd = isMat
                    ? ('loot-tracker --materials-info|' + stripMaterialSuffix(nm))
                    : ('loot-tracker --info|' + nm)
                const infoTip = isMaterialItem ? 'Инфо по материалу' : 'Подробнее (Инфо)'
                const takeCmd = 'loot-tracker --lootgen-take|' + nm
                const takeTypeCmd = 'loot-tracker --lootgen-take-type|' + nm

                return "" +
                    "<div style='margin:4px 0; border-bottom:1px solid #555; padding:4px 2px; display:inline-block; width:100%;'>" +
                    "  <div style='display:inline-block; width:68%; vertical-align:top; text-align:left;'>" +
                    "    <div style='color:#fff; word-wrap:break-word; overflow-wrap:break-word;'>" +
                    "      <span style='display:block; font-weight:bold;'>" + htmlEscape(nm) + "</span>" +
                    "      <span style='display:block; font-size:0.9em; color:#ccc;'>" +
                    "Кол-во: " + htmlEscape(q) + " · вес: " + htmlEscape(totalW) + " фнт" +
                    "</span>" +
                    "    </div>" +
                    "  </div>" +
                    "  <div style='display:inline-block; width:30%; text-align:right; vertical-align:top;'>" +
                    btn('❓', infoCmd, infoTip) +
                    btn('⬇', takeCmd, 'Забрать 1 шт в инвентарь') +
                    btn('⬇⬇', takeTypeCmd, 'Забрать ВСЕ этого типа в инвентарь') +
                    "  </div>" +
                    "</div>"
            }).join('')
            : "<div style='color:#ccc; text-align:left; padding:6px 2px;'>Пусто</div>"

        const html =
            openReport +
            openHeader + "Сгенерированный лут" + closeHeader +
            capBlock +
            receiptBlock +
            topBtns +
            coinsBlock +
            body +
            closeReport

        sayPublic(html)
    }

    function lootgenTakeOne(rawName, playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const name = String(rawName || '').trim()
        if (!name) return renderLootGenToChat()

        const lg = getLootGenStore()
        const key = findKeyInsensitiveIn(lg.items, name) // ВОТ ЭТО ВАЖНО
        if (!key) return renderLootGenToChat()

        const rec = lg.items[key]
        if (!rec) return renderLootGenToChat()

        invAddQtySilent(key, 1, rec.unitWeight)

        rec.qty = toNumber(rec.qty, 0) - 1
        if (rec.qty <= 0) delete lg.items[key] // удаляем по реальному ключу

        renderLootGenToChat(["• " + htmlEscape(key) + " × 1"])
    }

    function lootgenTakeAll(playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        const lg = getLootGenStore()
        const names = Object.keys(lg.items || {})
        const coinsRec = lg.coins || { pm: 0, zm: 0, sm: 0, mm: 0 }
        const hasCoins = coinsToMm(coinsRec) > 0
        if (!names.length && !hasCoins) return renderLootGenToChat()

        const receipt = []
        names.sort((a, b) => a.localeCompare(b, 'ru'))

        names.forEach(nm => {
            const rec = lg.items[nm]
            const q = Math.floor(toNumber(rec && rec.qty, 0))
            if (q > 0) {
                invAddQtySilent(nm, q, rec.unitWeight)
                receipt.push("• " + htmlEscape(nm) + " × " + htmlEscape(q))
            }
        })

        const addMm = coinsToMm(coinsRec)
        if (addMm > 0) {
            const store = getStore()
            const curMm = coinsToMm(store.coins || {})
            store.coins = mmToCoins(curMm + addMm)
            receipt.push("• Монеты: " + htmlEscape(coinsToText(coinsRec)))
        }

        lg.items = {}
        lg.coins = { pm: 0, zm: 0, sm: 0, mm: 0 }

        renderLootGenToChat(receipt)
    }

    function lootgenGenerate(rawArg, playerid) {
        if (!canEdit(playerid)) {
            return whisper(playerid, openReport + "<div style='color:#fff;'>Недостаточно прав (нужен ГМ)</div>" + closeReport)
        }

        // формат: value|types|magic|maxSlots|coins
        const parts = String(rawArg || '').split('|').map(s => (s || '').trim())
        const targetValue = Math.max(0, Math.floor(toNumber(parts[0], 0)))
        const typesList = parseTypesList(parts[1])
        const magicMode = parts[2] || 'нет'
        const maxSlotsRaw = parts[3]
        const coinsMode = parts[4] || 'нет'
        const maxSlots = (maxSlotsRaw === undefined || maxSlotsRaw === '')
            ? 9999
            : Math.max(1, Math.floor(toNumber(maxSlotsRaw, 9999)))

        const candidates = filterCandidatesByParams(typesList, magicMode)

        const coinTargetMm = targetValue * 10 // value приходит в см, конвертируем в мм

        const lg = getLootGenStore()
        lg.items = {}
        lg.coins = lootgenCoinModeEnabled(coinsMode) ? splitMmToBalancedCoins(coinTargetMm) : { pm: 0, zm: 0, sm: 0, mm: 0 }

        if (targetValue <= 0 || !candidates.length) {
            return renderLootGenToChat()
        }

        // 1) генерируем список выпавших предметов (могут повторяться)
        const drops = LOOTGEN_STRATEGY(targetValue, candidates, 9999) || []

        // 2) превращаем список в map name -> { qty, value, unitWeight }
        const chosen = {}
        for (let i = 0; i < drops.length; i++) {
            const it = drops[i]
            if (!it || !it.name) continue

            const nm = it.name
            chosen[nm] = chosen[nm] || {
                qty: 0,
                value: Math.floor(toNumber(it.value, 0)),
                unitWeight: nice2(toNumber(it.unitWeight, 0))
            }

            chosen[nm].qty += 1

            // ограничение по maxSlots: считаем "слоты" как количество уникальных позиций
            if (Object.keys(chosen).length > maxSlots) {
                // откат последнего добавления
                chosen[nm].qty -= 1
                if (chosen[nm].qty <= 0) delete chosen[nm]
                break
            }
        }

        lg.items = chosen
        renderLootGenToChat()
    }
    
    // ───────────────────────────────────────────────────────────────────────────
    // LOOTGEN: стратегии подбора (можно легко менять)
    // ───────────────────────────────────────────────────────────────────────────

    function normalizeLootItems(items) {
        if (Array.isArray(items)) return items.filter(Boolean)

        // items как объект: key -> { value, unitWeight, ... }
        return Object.entries(items || {}).map(([key, val]) => {
            return Object.assign({}, (val || {}), { name: key })
        }).filter(Boolean)
    }

    function getLoot(maxValue, items, maxTry = 9999) {
        let pool = normalizeLootItems(items)

        maxValue = Math.max(0, Math.floor(toNumber(maxValue, 0)))
        maxTry = Math.max(1, Math.floor(toNumber(maxTry, 9999)))

        let totalValue = 0
        const loot = []
        let _try = 0

        while (totalValue < maxValue && _try < maxTry) {
            _try += 1

            const remaining = maxValue - totalValue
            const afford = pool.filter(i => i && toNumber(i.value, 0) > 0 && toNumber(i.value, 0) <= remaining)

            if (!afford.length) break

            const randomIndex = Math.floor(Math.random() * afford.length)
            const randomItem = afford[randomIndex]
            if (!randomItem) break

            totalValue += Math.floor(toNumber(randomItem.value, 0))
            loot.push(randomItem)
        }

        return loot
    }

    // ПЕРЕКЛЮЧАТЕЛЬ: какую стратегию использовать для генерации
    const LOOTGEN_STRATEGY = getLoot

    // ───────────────────────────────────────────────────────────────────────────
    // УТИЛИТЫ: ПЕРСОНАЖИ/СИЛА/CON/ИСТОЩЕНИЕ/ЭНЕРГИЯ
    // ───────────────────────────────────────────────────────────────────────────
    function findCharacterByIdOrName(idOrName) {
        const s = String(idOrName || '').trim()
        if (!s) return null

        const byId = getObj('character', s)
        if (byId) return byId

        const list = findObjs({ type: 'character', name: s }) || []
        if (list.length) return list[0]

        const all = findObjs({ type: 'character' }) || []
        const low = s.toLowerCase()
        for (let i = 0; i < all.length; i++) {
            const nm = String(all[i].get('name') || '').toLowerCase()
            if (nm === low) return all[i]
        }
        for (let i = 0; i < all.length; i++) {
            const nm = String(all[i].get('name') || '').toLowerCase()
            if (nm.indexOf(low) !== -1) return all[i]
        }

        return null
    }

    function readStrengthFromSheet(characterId) {
        const candidates = [
            'strength',
            'STR',
            'str',
            'strength_score',
            'strength_base',
            'attr_strength'
        ]

        for (let i = 0; i < candidates.length; i++) {
            const a = findObjs({ type: 'attribute', characterid: characterId, name: candidates[i] }) || []
            if (a.length) {
                const v = toNumber(a[0].get('current'), NaN)
                if (!isNaN(v) && v > 0) return v
            }
        }
        return null
    }

    function readFirstAttributeNumber(characterId, names) {
        for (let i = 0; i < names.length; i++) {
            const a = findObjs({ type: 'attribute', characterid: characterId, name: names[i] }) || []
            if (a.length) {
                const v = toNumber(a[0].get('current'), NaN)
                if (!isNaN(v)) return v
            }
        }
        return null
    }

    function abilityModFromScore(score) {
        score = Math.floor(toNumber(score, NaN))
        if (isNaN(score)) return null
        return Math.floor((score - 10) / 2)
    }

    function readConModFromSheet(characterId) {
        const mod = readFirstAttributeNumber(characterId, CON_MOD_ATTR_CANDIDATES)
        if (mod !== null) return Math.floor(mod)

        const score = readFirstAttributeNumber(characterId, CON_SCORE_ATTR_CANDIDATES)
        const derived = abilityModFromScore(score)
        if (derived !== null) return derived

        return null
    }

    function getOrCreateAttr(characterId, name, defaultValue) {
        const a = findObjs({ type: 'attribute', characterid: characterId, name }) || []
        if (a.length) return a[0]
        return createObj('attribute', {
            characterid: characterId,
            name,
            current: defaultValue
        })
    }

    function readExhaustion(characterId) {
        const v = readFirstAttributeNumber(characterId, EXHAUSTION_ATTR_CANDIDATES)
        if (v === null) return 0
        return Math.max(0, Math.floor(v))
    }

    function addExhaustion(characterId, delta) {
        delta = Math.floor(toNumber(delta, 0))
        if (delta <= 0) return

        let foundName = null
        for (let i = 0; i < EXHAUSTION_ATTR_CANDIDATES.length; i++) {
            const nm = EXHAUSTION_ATTR_CANDIDATES[i]
            const a = findObjs({ type: 'attribute', characterid: characterId, name: nm }) || []
            if (a.length) {
                foundName = nm
                break
            }
        }
        if (!foundName) foundName = EXHAUSTION_ATTR_CANDIDATES[0]

        const cur = readExhaustion(characterId)
        const next = Math.max(0, cur + delta)
        const attr = getOrCreateAttr(characterId, foundName, cur)
        attr.set('current', next)
    }

    function getMemberEffectiveStr(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return { str: 0, source: 'нет' }

        if (m.strOverride !== undefined && m.strOverride !== null && m.strOverride !== '') {
            const v = toNumber(m.strOverride, NaN)
            if (!isNaN(v) && v > 0) return { str: v, source: 'ручн.' }
        }

        const fromSheet = readStrengthFromSheet(memberId)
        if (fromSheet) return { str: fromSheet, source: 'лист' }

        return { str: 0, source: '?' }
    }

    function getMemberCapMod(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        const def = toNumber(store.party.defaultCapMod, 15) || 15
        if (!m) return def

        if (m.capModOverride !== undefined && m.capModOverride !== null && m.capModOverride !== '') {
            const v = toNumber(m.capModOverride, NaN)
            if (!isNaN(v) && v > 0) return v
        }

        return def
    }

    function getMemberCapacityBonusLb(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return 0

        const v = toNumber(m.capBonusLb, 0)
        return isNaN(v) ? 0 : nice2(v)
    }

    function getMemberRole(member) {
        const role = String((member && member.role) || 'member').trim().toLowerCase()

        if (role === 'mount' || role === 'transport' || role === 'member') return role

        if (role === 'скакун' || role === 'mount') return 'mount'
        if (role === 'транспорт' || role === 'transport') return 'transport'
        if (role === 'член команды' || role === 'член') return 'member'

        return 'member'
    }

    function getRoleLabel(role) {
        if (role === 'mount') return 'Скакун'
        if (role === 'transport') return 'Транспорт'
        return 'Член команды'
    }

    function normalizeConsumeUnit(unit) {
        const u = String(unit || '').trim().toLowerCase()
        if (u === 'gal' || u === 'gallon' || u === 'gallons' || u === 'гал' || u === 'галлон' || u === 'галлоны') return 'gal'
        return 'lb'
    }

    function getDefaultConsumptionRulesByRole(role) {
        if (role === 'transport') return []
        if (role === 'mount') {
            return [
                { key: 'food', resource: FOOD_ITEM_NAME, amount: 2, unit: 'lb' },
                { key: 'water', resource: WATER_ITEM_NAME, amount: 2, unit: 'gal' }
            ]
        }
        return [
            { key: 'food', resource: FOOD_ITEM_NAME, amount: 1, unit: 'lb' },
            { key: 'water', resource: WATER_ITEM_NAME, amount: 1, unit: 'gal' }
        ]
    }

    function getMemberConsumptionRules(memberId) {
        const store = getStore()
        const m = store.party && store.party.members ? store.party.members[memberId] : null
        if (!m) return []

        const role = getMemberRole(m)
        if (!Array.isArray(m.consumptionRules)) {
            const base = getDefaultConsumptionRulesByRole(role)
            const food = (m.foodPerDay === undefined || m.foodPerDay === null) ? null : toNumber(m.foodPerDay, NaN)
            const water = (m.waterGalPerDay === undefined || m.waterGalPerDay === null) ? null : toNumber(m.waterGalPerDay, NaN)

            m.consumptionRules = base.map(r => {
                if (r.key === 'food' && !isNaN(food)) return { key: r.key, resource: r.resource, amount: Math.max(0, nice2(food)), unit: r.unit }
                if (r.key === 'water' && !isNaN(water)) return { key: r.key, resource: r.resource, amount: Math.max(0, nice2(water)), unit: r.unit }
                return { key: r.key, resource: r.resource, amount: r.amount, unit: r.unit }
            })
        }

        const cleaned = []
        m.consumptionRules.forEach(r => {
            if (!r) return
            const resource = String(r.resource || '').trim()
            if (!resource) return
            const amount = Math.max(0, toNumber(r.amount, 0))
            const unit = normalizeConsumeUnit(r.unit)
            const key = String(r.key || '').trim().toLowerCase()
            cleaned.push({ key: key, resource: resource, amount: nice2(amount), unit: unit })
        })
        m.consumptionRules = cleaned

        const foodRule = m.consumptionRules.find(r => r.key === 'food')
        const waterRule = m.consumptionRules.find(r => r.key === 'water')
        m.foodPerDay = foodRule ? nice2(foodRule.amount) : 0
        m.waterGalPerDay = waterRule ? nice2(waterRule.amount) : 0

        return m.consumptionRules
    }

    function getRuleNeedLb(rule) {
        const amount = Math.max(0, toNumber(rule && rule.amount, 0))
        if (normalizeConsumeUnit(rule && rule.unit) === 'gal') return amount * WATER_LB_PER_GALLON
        return amount
    }

    function getMemberFoodNeedLb(memberId) {
        const rules = getMemberConsumptionRules(memberId)
        const r = rules.find(x => x.key === 'food')
        return r ? Math.max(0, toNumber(r.amount, 0)) : 0
    }

    function getMemberWaterNeedGal(memberId) {
        const rules = getMemberConsumptionRules(memberId)
        const r = rules.find(x => x.key === 'water')
        return r ? Math.max(0, toNumber(r.amount, 0)) : 0
    }

    function renderMemberConsumptionShort(memberId) {
        const rules = getMemberConsumptionRules(memberId)
        if (!rules.length) return 'Расход/день: нет'

        return 'Расход/день: ' + rules.map(r => {
            const unitLabel = normalizeConsumeUnit(r.unit) === 'gal' ? 'галл' : 'фнт'
            return htmlEscape(r.resource) + ' ' + htmlEscape(nice2(r.amount)) + ' ' + unitLabel
        }).join(' · ')
    }

    function getMemberConMod(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return { mod: null, source: 'нет' }

        if (m.conModOverride !== undefined && m.conModOverride !== null && m.conModOverride !== '') {
            const v = toNumber(m.conModOverride, NaN)
            if (!isNaN(v)) return { mod: Math.floor(v), source: 'ручн.' }
        }

        const fromSheet = readConModFromSheet(memberId)
        if (fromSheet !== null) return { mod: Math.floor(fromSheet), source: 'лист' }

        return { mod: null, source: '?' }
    }

    function getMemberEnergyMax(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return ENERGY_MIN_DAYS

        if (m.energyMaxOverride !== undefined && m.energyMaxOverride !== null && m.energyMaxOverride !== '') {
            const v = toNumber(m.energyMaxOverride, NaN)
            if (!isNaN(v)) return Math.max(ENERGY_MIN_DAYS, Math.floor(v))
        }

        const con = getMemberConMod(memberId)
        const conMod = (con.mod === null ? 0 : con.mod)
        return Math.max(ENERGY_MIN_DAYS, ENERGY_BASE_DAYS + conMod)
    }

    function getMemberEnergyCur(memberId) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return 0

        const maxE = getMemberEnergyMax(memberId)
        let cur = m.energyCur
        if (cur === null || cur === undefined || cur === '') cur = maxE
        cur = Math.floor(toNumber(cur, maxE))
        if (isNaN(cur)) cur = maxE

        cur = Math.max(0, Math.min(maxE, cur))
        return cur
    }

    function setMemberEnergyCur(memberId, nextCur) {
        const store = getStore()
        const m = store.party.members[memberId]
        if (!m) return

        const maxE = getMemberEnergyMax(memberId)
        nextCur = Math.floor(toNumber(nextCur, 0))
        if (isNaN(nextCur)) nextCur = 0

        m.energyCur = Math.max(0, Math.min(maxE, nextCur))
    }
    
    function mmToCoins(mmTotal) {
        let mm = Math.floor(mmTotal + 1e-9)
        if (!isFinite(mm) || mm <= 0) return { pm: 0, zm: 0, sm: 0, mm: 0 }
    
        const pm = Math.floor(mm / 1000)
        mm = mm % 1000
        const zm = Math.floor(mm / 100)
        mm = mm % 100
        const sm = Math.floor(mm / 10)
        mm = mm % 10
    
        return { pm, zm, sm, mm }
    }
    
    const COIN_TO_MM = { mm: 1, sm: 10, zm: 100, pm: 1000 }

    function coinsToMm(coins) {
        coins = coins || { pm: 0, zm: 0, sm: 0, mm: 0 }
        const pm = Math.floor(toNumber(coins.pm, 0))
        const zm = Math.floor(toNumber(coins.zm, 0))
        const sm = Math.floor(toNumber(coins.sm, 0))
        const mm = Math.floor(toNumber(coins.mm, 0))
    
        return pm * 1000 + zm * 100 + sm * 10 + mm
    }

