    // ───────────────────────────────────────────────────────────────────────────
    // PARTY: TOOLS (личные профили для крафта)
    // ───────────────────────────────────────────────────────────────────────────
    function showPartyToolsWindow(rawArg, playerid) {
        const editable = canEdit(playerid)
    
        const memberId = String(rawArg || '').trim()
        const store = getStore()
    
        migrateCraft(store)
    
        const m = store.party && store.party.members ? store.party.members[memberId] : null
        if (!m) {
            whisper(playerid, openHeader + "<div>Не найден участник команды: " + htmlEscape(memberId) + "</div>" + closeHeader)
            return
        }
    
        const rows = TOOL_LIST.map(t => {
            const tool = String(t || '').trim()
            if (!tool) return ''
    
            const tp = getMemberToolProfile(m, tool) || { owned: false, prof: false, mod: 0 }
            const owned = !!tp.owned
            const prof = !!tp.prof
            const mod = toNumber(tp.mod, 0)
    
            const ownedCmd = 'loot-tracker --party-tool-owned|' + memberId + '|' + tool
            const profCmd  = 'loot-tracker --party-tool-prof|' + memberId + '|' + tool
            const modCmd   = 'loot-tracker --party-tool-mod|' + memberId + '|' + tool + '|?{Модификатор (можно +1/-1 или число)|' + nice0(mod) + '}'
    
            const ownedBtn = editable ? btn(owned ? '✅' : '⬜', ownedCmd, owned ? 'Инструмент есть' : 'Инструмента нет') : (owned ? '✅' : '⬜')
            const profBtn  = editable ? btn(prof ? '✅' : '⬜', profCmd, prof ? 'Владение есть' : 'Владения нет') : (prof ? '✅' : '⬜')
            const modBtn   = editable ? btn((mod >= 0 ? '+' : '') + nice0(mod), modCmd, 'Модификатор крафта') : ((mod >= 0 ? '+' : '') + nice0(mod))
    
            return "<tr>" +
                "<td style='padding:2px 6px 2px 0; border-bottom:1px solid #333; vertical-align:middle;'>" +
                    htmlEscape(tool) +
                "</td>" +
                "<td style='padding:2px 0; border-bottom:1px solid #333; text-align:right; white-space:nowrap; vertical-align:middle;'>" +
                    "<span style='display:inline-block; width:26px; text-align:center;'>" + ownedBtn + "</span>" +
                    "<span style='display:inline-block; width:26px; text-align:center;'>" + profBtn  + "</span>" +
                    "<span style='display:inline-block; width:44px; text-align:center;'>" + modBtn   + "</span>" +
                "</td>" +
            "</tr>"
        }).join('')
    
        const nav = renderNav(['party', 'craftQueue', 'inventory', 'menu'], editable)
    
        const html =
            openHeader +
            "<div style='margin-bottom:6px;'><b>Инструменты:</b> " + htmlEscape(m.name || m.id) + "</div>" +
            "<div style='font-size:0.9rem; opacity:0.85; margin-bottom:6px;'>" +
                "Наличие — есть ли инструменты у персонажа. Владение/Мод — личные параметры персонажа." +
            "</div>" +
            "<table style='width:100%; border-collapse:collapse;'>" + rows + "</table>" +
            "<div style='margin-top:6px;'>" + nav + "</div>" +
            closeHeader
    
        whisper(playerid, html)
    }

function togglePartyToolOwned(rawArg, playerid) {
    if (!canEdit(playerid)) return showPartyWindow(playerid)

    const parts = String(rawArg || '').split('|').map(s => (s || '').trim())
    const memberId = parts[0] || ''
    const tool = parts[1] || ''

    const store = getStore()
    migrateCraft(store)

    const m = store.party && store.party.members ? store.party.members[memberId] : null
    if (!m) return showPartyWindow(playerid)

    const tp = getMemberToolProfile(m, tool)
    if (!tp) return showPartyToolsWindow(memberId, playerid)

    tp.owned = !tp.owned

    showPartyToolsWindow(memberId, playerid)
}

